@GetMapping("/api/orders/{id}")
public OrderDto get(@PathVariable long id, Principal caller) {
    Order order = orders.findById(id).orElseThrow();
    if (!order.getOwner().equals(caller.getName())) {
        throw new ForbiddenException();   // -> 403
    }
    return toDto(order);
}
